    if (!title) { formMessage(form, '[data-file-message]', 'Add a project title to continue.'); form.elements.title.focus(); return; } if (sourceLanguage === targetLanguage) { formMessage(form, '[data-file-message]', 'Choose different source and target languages.'); form.elements.targetLanguage.focus(); return; } if (!form.elements.authorization.checked) { formMessage(form, '[data-file-message]', 'Confirm that you have permission to process this screenplay.'); form.elements.authorization.focus(); return; } const fileCheck = validateFile(file); if (!fileCheck.valid) { formMessage(form, '[data-file-message]', fileCheck.message); return; } if (!file && !pasted) { formMessage(form, '[data-file-message]', 'Upload a screenplay or paste text. No fallback excerpt is used automatically.'); form.elements.screenplay.focus(); return; }
