    catch (error) { state.modalSaving = false; const message = errorMessage(error); form.querySelectorAll('input,select,textarea,button').forEach((field) => { field.disabled = false; }); if (button) button.innerHTML = `${icon('plus')}Create project`; formMessage(form, '[data-file-message]', message); if (error.status === 0) state.server.online = false; }
