  async function deleteSourceFile(fileId) { if (!fileId || !window.confirm('Delete this source file? The server will cascade its parsed scenes and segments for this project.')) return; setBusy(`file-${fileId}`, true); render(); try { await api(`${projectPath()}/files/${encodeURIComponent(fileId)}`, { method: 'DELETE' }); setBusy(`file-${fileId}`, false); await refreshBundle(); toast('Source file and its parsed content were deleted.', 'info'); } catch (error) { setBusy(`file-${fileId}`, false); setError('global', error); render(); } }
